<?php
declare(strict_types=1);use App\Core\Auth\Auth;use App\Core\Database\Database;use App\Core\Exceptions\BusinessRuleException;use App\Modules\SupplierPayments\DTOs\SupplierPaymentData;use App\Modules\SupplierPayments\Services\SupplierPaymentService;/** @var Database$db */$db=$app->make(Database::class);/** @var SupplierPaymentService$s */$s=$app->make(SupplierPaymentService::class);/** @var Auth$auth */$auth=$app->make(Auth::class);$user=$db->execute('SELECT id,name,username FROM users WHERE is_active=1 LIMIT 1')->fetch_assoc();if(!$user)throw new RuntimeException('User fixture missing.');$x=(string)random_int(100000,999999);$client=$vendor=$project=$invoice=0;$payments=[];
try{$db->execute("INSERT INTO clients(client_code,client_type,name)VALUES(?,'individual','SP Client')",['SPC-'.$x]);$client=(int)$db->connection()->insert_id;$db->execute("INSERT INTO vendors(vendor_code,vendor_type,name)VALUES(?,'supplier','SP Vendor')",['SPV-'.$x]);$vendor=(int)$db->connection()->insert_id;$db->execute("INSERT INTO projects(project_code,name,client_id,project_type,status)VALUES(?,'SP Project',?,'contracting','active')",['SPP-'.$x,$client]);$project=(int)$db->connection()->insert_id;$db->execute("INSERT INTO supplier_invoices(invoice_code,vendor_id,project_id,invoice_number,invoice_date,total_amount,status,vendor_code_snapshot,vendor_name_snapshot,project_code_snapshot,project_name_snapshot,created_by,approved_at,approved_by)VALUES(?,?,?,?,?,'0.30','approved',?,?,?,?,?,NOW(),?)",['SINV-T-'.$x,$vendor,$project,'INV-'.$x,'2026-09-01','SPV-'.$x,'SP Vendor','SPP-'.$x,'SP Project',(int)$user['id'],(int)$user['id']]);$invoice=(int)$db->connection()->insert_id;$auth->login($user);
$p1=$s->save(new SupplierPaymentData($invoice,'2026-09-10','0.10','cash',null,null));$payments[]=$p1;$p2=$s->save(new SupplierPaymentData($invoice,'2026-09-11','0.20','bank_transfer',null,null));$payments[]=$p2;$s->post($p1);$a=$s->find($p1);if($a['previous_paid_snapshot']!=='0.00'||$a['remaining_payable_snapshot']!=='0.20')throw new RuntimeException('Exact decimal snapshots failed.');$s->post($p2);$summary=$s->summary($invoice);if($summary['paid']!=='0.30'||$summary['remaining']!=='0.00')throw new RuntimeException('Exact decimal total failed.');try{$s->post($p2);throw new RuntimeException('Double post accepted.');}catch(BusinessRuleException){}$over=$s->save(new SupplierPaymentData($invoice,'2026-09-12','0.01','cash',null,null));$payments[]=$over;try{$s->post($over);throw new RuntimeException('Overpayment accepted.');}catch(BusinessRuleException){}
$db->execute("UPDATE supplier_invoices SET total_amount='1.30' WHERE id=?",[$invoice]);$c1=$s->save(new SupplierPaymentData($invoice,'2026-09-12','0.80','cash',null,null));$payments[]=$c1;$c2=$s->save(new SupplierPaymentData($invoice,'2026-09-12','0.80','cash',null,null));$payments[]=$c2;$s->post($c1);try{$s->post($c2);throw new RuntimeException('Concurrent stale payment exceeded invoice.');}catch(BusinessRuleException){}try{$s->save(new SupplierPaymentData($invoice,'2026-09-12','0.50','cash',null,null),$c1);throw new RuntimeException('Posted payment mutable.');}catch(BusinessRuleException){}$cancel=$s->save(new SupplierPaymentData($invoice,'2026-09-12','0.10','cash',null,null));$payments[]=$cancel;$before=$s->summary($invoice)['paid'];$s->cancel($cancel);if($s->summary($invoice)['paid']!==$before)throw new RuntimeException('Cancelled draft affected payable.');$costs=$db->execute("SELECT COUNT(*) n FROM project_actual_costs WHERE source_type='supplier_invoice' AND source_id=?",[$invoice])->fetch_assoc();if((int)$costs['n']!==0)throw new RuntimeException('Supplier payment created project cost.');}
finally{$auth->logout();foreach($payments as$p)$db->execute('DELETE FROM supplier_payments WHERE id=?',[$p]);$invoice&&$db->execute('DELETE FROM supplier_invoices WHERE id=?',[$invoice]);$project&&$db->execute('DELETE FROM projects WHERE id=?',[$project]);$vendor&&$db->execute('DELETE FROM vendors WHERE id=?',[$vendor]);$client&&$db->execute('DELETE FROM clients WHERE id=?',[$client]);}
